可用两个页面完成自动填充，核心代码如下：
1. login.jsp
<%@ page import="java.net.URLDecoder,javax.servlet.http.Cookie" %>
<%
String uname="";
String upwd="";
Cookie[] cookies=request.getCookies();
if(cookies!=null){
  for(Cookie c:cookies){
    if("uname".equals(c.getName())) uname=URLDecoder.decode(c.getValue(),"UTF-8");
    if("upwd".equals(c.getName())) upwd=URLDecoder.decode(c.getValue(),"UTF-8");
  }
}
%>
<form action="save.jsp" method="post">
  用户名：<input type="text" name="uname" value="<%=uname%>"><br>
  密码：<input type="text" name="upwd" value="<%=upwd%>"><br>
  <input type="submit" value="保存">
</form>

2. save.jsp
<%@ page import="java.net.URLEncoder,javax.servlet.http.Cookie" %>
<%
String uname=request.getParameter("uname");
String upwd=request.getParameter("upwd");
Cookie c1=new Cookie("uname",URLEncoder.encode(uname,"UTF-8"));
Cookie c2=new Cookie("upwd",URLEncoder.encode(upwd,"UTF-8"));
c1.setMaxAge(7*24*3600);
c2.setMaxAge(7*24*3600);
response.addCookie(c1);
response.addCookie(c2);
response.sendRedirect("login.jsp");
%>

